import { gql } from '@apollo/client'

export const VerifyUser = gql`
  mutation verifyUser(
    $id: String!
    $password: String!
  ) {
    verifyUser (
      data: { id: $id, password: $password }
    ) {
      id
      name
      email
      admin
      access_token
      id_token
      picture
      companies {
        id
        role
        company {
          id
          name
          demGroups {
            id
            groupId
          }
        }
      }
    }
  }
`

export interface VerifyUserArgs {
  id: string;
  password: string;
}

export interface VerifyUserRes {
  verifyUser: {
    id: string
    access_token: string;
    id_token: string;
    name: string;
    email: string;
    admin: boolean;
    picture: string;
    companies: {
      id: string;
      role: string;
      company: {
        id: string;
        name: string;
        demGroups: {
          id: string;
          groupId: string;
        }[]
      }
    }[]
  }
}